"""A deliberately small model of the Mermaid flowchart subset the fixtures use.
Self-check only; not shipped. Mirrors the pre-registration's Appendix A as read by F."""
import re
from itertools import combinations

FENCE_OPEN = re.compile(r"^ {0,3}(`{3,}|~{3,})[ \t]*mermaid(-example)?\b", re.I)
HEADER = re.compile(r"^(flowchart|flowchart-elk|graph)(\s|$)")


class ParseError(Exception):
    pass


def fences(md):
    lines = md.split("\n")
    out, i = [], 0
    while i < len(lines):
        m = FENCE_OPEN.match(lines[i])
        if m:
            ch, n = m.group(1)[0], len(m.group(1))
            j = i + 1
            while j < len(lines) and not re.fullmatch(re.escape(ch) + "{%d,}" % n, lines[j]):
                j += 1
            out.append("\n".join(lines[i + 1:j]))
            i = j + 1
        else:
            i += 1
    return out


SHAPES = [("(((", ")))", "doublecircle"), ("([", "])", "stadium"), ("[[", "]]", "subroutine"),
          ("[(", ")]", "cylinder"), ("((", "))", "circle"), ("{{", "}}", "hexagon"),
          ("[/", "/]", "lean_right"), ("[\\", "\\]", "lean_left"), ("[/", "\\]", "trapezoid"),
          ("[\\", "/]", "inv_trapezoid"), (">", "]", "odd"), ("[", "]", "square"),
          ("(", ")", "round"), ("{", "}", "diamond")]
ARROWS = {"-->": ("solid", "none", "arrow"), "---": ("solid", "none", "none"),
          "-.->": ("dotted", "none", "arrow"), "-.-": ("dotted", "none", "none"),
          "==>": ("thick", "none", "arrow"), "===": ("thick", "none", "none"),
          "~~~": ("invisible", "none", "none"), "--o": ("solid", "none", "circle"),
          "--x": ("solid", "none", "cross"), "<-->": ("solid", "arrow", "arrow"),
          "o--o": ("solid", "circle", "circle"), "x--x": ("solid", "cross", "cross")}
ARROW_RE = re.compile(r"\s*(?:([A-Za-z_]\w*)@)?(<-->|o--o|x--x|-\.->|-\.-|-->|---|==>|===|~~~|--o|--x)(?:\|([^|]*)\|)?\s*")
ID_RE = re.compile(r"[A-Za-z_]\w*")


class Model:
    def __init__(self):
        self.v = {}          # id -> dict(label, shape, classes, styles, link, stmt)
        self.subs = []       # closing order: dict(key, id, title, members)
        self.edges = []      # dict(s, e, kind, label, uid)
        self.classdefs = {}
        self.dirs = []
        self.linkstyles = []
        self.mentions = []   # (id, block-stack tuple)
        self.node_stmt = set()
        self.label_set = {}  # id -> set of (label, shape) from node statements
        self.edge_ids_seen = []

    def vertex(self, vid):
        if vid not in self.v:
            self.v[vid] = dict(label=vid, shape=None, classes=[], styles=[], link=None)
        return self.v[vid]


def parse_vertex(s, i, m, stack):
    mm = ID_RE.match(s, i)
    if not mm:
        raise ParseError("id expected at %r" % s[i:])
    vid = mm.group(0)
    i = mm.end()
    label = shape = None
    if s.startswith("@{", i):
        j = s.index("}", i)
        body = s[i + 2:j]
        kv = dict((a.strip(), b.strip().strip('"')) for a, b in (p.split(":", 1) for p in re.split(r",\s*(?=\w+\s*:)", body)))
        shape, label = "@" + kv.get("shape", "rect"), kv.get("label", vid)
        i = j + 1
    else:
        for op, cl, name in SHAPES:
            if s.startswith(op, i):
                j = s.find(cl, i + len(op))
                if j < 0:
                    continue
                inner = s[i + len(op):j]
                if any(c in inner for c in "[](){}") and not inner.startswith('"'):
                    continue
                label, shape = inner.strip().strip('"').strip(), name
                i = j + len(cl)
                break
    cls = None
    if s.startswith(":::", i):
        mm = ID_RE.match(s, i + 3)
        cls = mm.group(0)
        i = mm.end()
    if vid in m.edge_ids_seen and shape is not None:
        return i, vid, True  # R drops the node statement
    vx = m.vertex(vid)
    if shape is not None:
        vx["label"], vx["shape"] = label, shape
        m.node_stmt.add(vid)
        m.label_set.setdefault(vid, set()).add((label, shape))
    if cls:
        vx["classes"].append(cls)
    m.mentions.append((vid, tuple(stack)))
    return i, vid, False


def parse(text):
    m = Model()
    lines = [l for l in text.split("\n")]
    body = []
    for l in lines:
        t = l.strip()
        if not t or t.startswith("%%"):
            continue
        body.append(t)
    if not body or not HEADER.match(body[0]):
        raise ParseError("not a flowchart")
    stack, blocks, n_auto = [], [], 0
    for t in body[1:]:
        if t.startswith("subgraph "):
            rest = t[len("subgraph "):].strip()
            mm = re.fullmatch(r"([A-Za-z_]\w*)\s*\[(.*)\]", rest)
            if mm:
                sid, title, explicit = mm.group(1), mm.group(2).strip().strip('"'), True
            elif re.fullmatch(r"[A-Za-z_]\w*", rest):
                sid, title, explicit = rest, rest, True
            else:
                sid, title, explicit = None, rest.strip('"'), False
            stack.append(dict(id=sid, title=title, explicit=explicit, mentioned=[]))
            continue
        if t == "end":
            b = stack.pop()
            if not b["explicit"]:
                b["id"] = "subGraph%d" % n_auto
            n_auto += 1
            b["key"] = b["id"] if b["explicit"] else "title:" + b["title"]
            m.subs.append(b)
            if stack:
                stack[-1]["mentioned"].append(("SUB", b["key"]))
                stack[-1]["mentioned"].extend(b["mentioned"])
            continue
        if t.startswith("direction "):
            m.dirs.append((tuple(x["title"] for x in stack), t.split()[1]))
            continue
        if t.startswith("classDef "):
            _, names, st = t.split(None, 2)
            for n in names.split(","):
                m.classdefs[n] = st
            continue
        if t.startswith("class "):
            _, ids, cls = t.split()
            for i_ in ids.split(","):
                if i_ in m.v:
                    m.v[i_]["classes"].append(cls)
                for e in m.edges:
                    if e["uid"] == i_:
                        e.setdefault("classes", []).append(cls)
            continue
        if t.startswith("style "):
            _, vid, st = t.split(None, 2)
            m.vertex(vid)["styles"].append(st)
            continue
        if t.startswith("linkStyle "):
            _, idx, st = t.split(None, 2)
            for i_ in idx.split(","):
                k = int(i_)
                if k >= len(m.edges):
                    raise ParseError("TypeError linkStyle out of range")
                m.edges[k]["style"] = st
            continue
        if t.startswith("click "):
            parts = t.split(None, 2)
            if parts[1] in m.v:
                m.v[parts[1]]["link"] = parts[2]
            continue
        # statement: vertex groups joined by arrows
        i = 0
        groups = []
        arrows = []
        while True:
            grp = []
            while True:
                i, vid, dropped = parse_vertex(t, i, m, [b for b in stack])
                if stack:
                    stack[-1]["mentioned"].append(("V", vid))
                grp.append(vid)
                mm = re.match(r"\s*&\s*", t[i:])
                if mm:
                    i += mm.end()
                    continue
                break
            groups.append(grp)
            if i >= len(t):
                break
            mm = ARROW_RE.match(t, i)
            if not mm:
                raise ParseError("bad statement %r at %r" % (t, t[i:]))
            arrows.append((mm.group(1), ARROWS[mm.group(2)], (mm.group(3) or "")))
            i = mm.end()
        for (uid, kind, label), a, b in zip(arrows, groups, groups[1:]):
            for s_ in a:
                for e_ in b:
                    u = uid
                    if u and any(e["uid"] == u for e in m.edges):
                        u = None
                    m.edges.append(dict(s=s_, e=e_, kind=kind, label=label, uid=u))
                    if u:
                        m.edge_ids_seen.append(u)
    if stack:
        raise ParseError("unclosed subgraph")
    return m


def units(m):
    """Return dict unit -> value. Units: ('exist',k) kind-set, ('label',k), ('shape',k), ('member',k),
    ('class',k,c), ('styles',k), ('link',k), ('count',relkey), ('estyle',relkey,n)."""
    U = {}
    sub_ids = {b["id"]: b["key"] for b in m.subs}
    def key_of(vid):
        if vid in sub_ids and vid not in m.node_stmt:
            return sub_ids[vid]
        return vid
    for vid, vx in m.v.items():
        if vid in sub_ids and vid not in m.node_stmt:
            continue
        U[("exist", vid)] = U.get(("exist", vid), frozenset()) | {"node"}
        U[("label", vid)] = vx["label"]
        U[("shape", vid)] = vx["shape"] or "none"
        for c in set(vx["classes"]):
            U[("class", vid, c)] = True
        U[("styles", vid)] = tuple(vx["styles"])
        U[("link", vid)] = vx["link"]
    for b in m.subs:
        k = b["key"]
        U[("exist", k)] = U.get(("exist", k), frozenset()) | {"subgraph"}
        U[("title", k)] = b["title"]
    # membership: first subgraph in closing order mentioning it
    for b in m.subs:
        for kind, x in b["mentioned"]:
            x = key_of(x) if kind == "V" else x
            if x == b["key"]:
                continue
            if ("member", x) not in U:
                U[("member", x)] = b["key"]
    for k in [u[1] for u in list(U) if u[0] == "exist"]:
        U.setdefault(("member", k), None)
    occ = {}
    for e in m.edges:
        if e["uid"]:
            k = e["uid"]
            U[("exist", k)] = U.get(("exist", k), frozenset()) | {"edge"}
            U[("eedge", k)] = (key_of(e["s"]), key_of(e["e"]), e["kind"], e["label"])
            rk = ("uid", k)
        else:
            rk = (key_of(e["s"]), key_of(e["e"]), e["kind"], e["label"])
            U[("count", rk)] = U.get(("count", rk), 0) + 1
        n = occ.get(rk, 0)
        occ[rk] = n + 1
        if e.get("style"):
            U[("estyle", rk, n)] = e["style"]
        for c in e.get("classes", []):
            U[("class", e["uid"], c)] = True
    for c, st in m.classdefs.items():
        U[("classdef", c)] = st
    for d in m.dirs:
        U[("dir",) + d[:1]] = d[1]
    return U


def order(m):
    sub_ids = {b["id"] for b in m.subs}
    return [v for v in m.v if not (v in sub_ids and v not in m.node_stmt)]


ABSENT = "<absent>"


def refs(u, val):
    """Keys a present unit refers to (excluding membership holders)."""
    if u[0] == "count":
        return {u[1][0], u[1][1]}
    if u[0] == "eedge":
        return {u[1], val[0], val[1]}
    if u[0] in ("label", "shape", "styles", "link", "title", "exist", "member"):
        return {u[1]}
    if u[0] == "class":
        return {u[1]}
    if u[0] == "estyle":
        return set(u[1][:2]) if u[1][0] != "uid" else {u[1][1]}
    return set()


def keyed(u):
    if u[0] in ("label", "shape", "styles", "link", "title", "exist", "member", "class", "eedge"):
        return u[1]
    return None


def lints(m):
    out = set()
    sub_ids = {b["id"] for b in m.subs}
    for vid in m.v:
        if vid in sub_ids and vid not in m.node_stmt:
            continue
        if vid not in m.node_stmt:
            out.add(("L1", vid))
        if len(m.label_set.get(vid, ())) > 1:
            out.add(("L2", vid))
    held = {}
    for b in m.subs:
        for kind, x in b["mentioned"]:
            if kind == "V":
                held.setdefault(x, set()).add(b["key"])
    # direct blocks only: subtract nesting (fixtures avoid nesting anyway)
    for x, hs in held.items():
        if len(hs) > 1:
            out.add(("L3", x))
    U = units(m)
    for u, val in U.items():
        if u[0] == "exist" and len(val) > 1:
            out.add(("L4", u[1]))
    seen = {}
    for e in m.edges:
        rk = e["uid"] or (e["s"], e["e"], e["kind"], e["label"])
        seen[rk] = seen.get(rk, 0) + 1
    for rk, n in seen.items():
        if n > 1:
            for x in (rk[:2] if isinstance(rk, tuple) else (rk,)):
                out.add(("L5", x))
    return out


def judge(B, O, T, M):
    mb, mo, mt, mm = (parse(x) for x in (B, O, T, M))
    ub, uo, ut, um = (units(x) for x in (mb, mo, mt, mm))
    allu = set(ub) | set(uo) | set(ut) | set(um)
    g = lambda U, u: U.get(u, ABSENT)
    dec, conflict = {}, set()
    for u in allu:
        b, o, t = g(ub, u), g(uo, u), g(ut, u)
        if o == t:
            dec[u] = o
        elif o == b:
            dec[u] = t
        elif t == b:
            dec[u] = o
        else:
            conflict.add(u)
    keys = {u[1] for u in allu if u[0] == "exist"}
    dabsent = {k for k in keys if dec.get(("exist", k), ABSENT) == ABSENT and ("exist", k) not in conflict}
    recs = []
    idkeys = set()
    # exposure
    exposed = False
    for k in keys:
        for L, Oth in ((uo, ut), (ut, uo)):
            if ("exist", k) in ub and ("exist", k) not in L:
                for u in allu:
                    if u[0] == "member" or u == ("exist", k):
                        if u[0] == "member" and u[1] == k and g(Oth, u) != g(ub, u):
                            exposed = True
                        continue
                    if g(Oth, u) != g(ub, u) and g(Oth, u) != ABSENT and k in refs(u, g(Oth, u)):
                        exposed = True
        if ("exist", k) not in ub and ("exist", k) in uo and ("exist", k) in ut:
            for u in allu:
                if keyed(u) == k and g(uo, u) != g(ut, u):
                    exposed = True
    # I1 dangling
    for u, val in dec.items():
        if val == ABSENT or u[0] in ("member", "exist"):
            continue
        for k in refs(u, val) & dabsent:
            objs = set()
            for u2, v2 in dec.items():
                if v2 != ABSENT and u2[0] not in ("member", "exist") and k in refs(u2, v2):
                    objs |= refs(u2, v2)
            recs.append(("I1", tuple(sorted(objs | {k}))))
            idkeys.add(k)
    # I2 collision
    for k in keys:
        if ("exist", k) not in ub and ("exist", k) in uo and ("exist", k) in ut:
            if any(keyed(u) == k and g(uo, u) != g(ut, u) for u in allu):
                recs.append(("I2", (k,)))
                idkeys.add(k)
    # I3 delete/modify
    for k in keys:
        for L, Oth in ((uo, ut), (ut, uo)):
            if ("exist", k) in ub and ("exist", k) not in L:
                if any(keyed(u) == k and u[0] != "exist" and g(Oth, u) != g(ub, u) for u in allu):
                    recs.append(("I3", (k,)))
                    idkeys.add(k)
    # I4
    for k in keys:
        kinds = [g(x, ("exist", k)) for x in (ub, uo, ut)]
        if all(kk == ABSENT or len(kk) == 1 for kk in kinds):
            mk = g(um, ("exist", k))
            dk = dec.get(("exist", k))
            if mk != ABSENT and (len(mk) > 1 or (dk not in (None, ABSENT) and mk != dk)):
                recs.append(("I4", (k,)))
                idkeys.add(k)
    for u in allu:
        if u[0] == "exist" and u not in conflict and g(um, u) != dec[u] and u[1] not in idkeys:
            if (g(um, u) == ABSENT) != (dec[u] == ABSENT):
                recs.append(("G1", (u[1],)))
                idkeys.add(u[1])
    for u in sorted(allu, key=repr):
        k = keyed(u)
        if k in idkeys:
            continue
        mv = g(um, u)
        if u in conflict:
            if mv not in (g(uo, u), g(ut, u)):
                cat = {"count": "G2", "member": "G3", "label": "G4", "title": "G4", "link": "G4",
                       "shape": "C"}.get(u[0], "D")
                if u[0] == "estyle":
                    cat = "S-LINKSTYLE"
                recs.append(("MC/" + cat, repr(u)))
            continue
        dv = dec[u]
        if mv == dv:
            continue
        if u[0] == "exist":
            recs.append(("G1", (k,)))
        elif u[0] == "count":
            recs.append(("G2", tuple(sorted(u[1][:2])), "lost" if mv == ABSENT or (dv != ABSENT and mv < dv) else "extra"))
        elif u[0] == "member":
            hs = {dv, mv} - {None, ABSENT}
            if any(h in dabsent for h in hs | {g(ub, u), g(uo, u), g(ut, u)} - {None, ABSENT}):
                continue
            recs.append(("G3", tuple(sorted({k} | hs))))
        elif u[0] in ("label", "title", "link", "eedge"):
            recs.append(("G4", (k,)))
        elif u[0] == "shape":
            recs.append(("C", (k,)))
        elif u[0] == "estyle":
            recs.append(("S-LINKSTYLE", tuple(sorted(u[1][:2]))))
        else:
            recs.append(("D", repr(u)))
    # order: pairs present in all four
    ob, oo, ot, om = (order(x) for x in (mb, mo, mt, mm))
    common = set(ob) & set(oo) & set(ot) & set(om)
    for a, b in combinations(sorted(common), 2):
        f = lambda L: L.index(a) < L.index(b)
        vb, vo, vt = f(ob), f(oo), f(ot)
        d = vo if vo == vt else (vt if vo == vb else (vo if vt == vb else None))
        if d is not None and f(om) != d:
            recs.append(("S-ORDER", (a, b)))
    lb, lo, lt, lm = (lints(x) for x in (mb, mo, mt, mm))
    new = lm - lb - lo - lt
    return dict(records=recs, exposed=exposed, new_lints=sorted(new))
